public NanoHTTPD.Response serve(NanoHTTPD server,Properties parms,RequestType type){
    try {
        switch (type) {
            case help:    return wrap(server,HTMLHelp());
            case json:case www:  return serveGrid(server,parms,type);
            case query:{
                for (  Argument arg : _arguments)   arg.reset();
                String query=buildQuery(parms,type);
                return wrap(server,query);
            }
            case java:checkArguments(parms,type);
            String javacode=serveJava();
            return wrap(server,javacode,RequestType.java);
            default:throw new RuntimeException("Invalid request type " + type.toString());
        }
    } catch (IndexOutOfBoundsException e) {
        throw new RuntimeException("Invalid argument name format", e);
    } catch (ClassCastException e) {
        throw new RuntimeException("Invalid property type", e);
    }
}
